import {products,reasons,employers,seedState,diagnostics,capture,impact,experimentResult,gate,authorize,placeOrder} from './engine.js';
const $=s=>document.querySelector(s),KEY='rethread-pilot-v1';let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.version!==1)state=seedState()}catch{state=seedState()}let view=location.hash.slice(1)||'overview',selected='NV-101-M',search='',filter='all',demoStep=0;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);const pct=n=>(n*100).toFixed(1)+'%';
const paths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',inbox:'M4 4h16v16H4zM4 14h5l2 3h2l2-3h5M12 7v5m-3-3 3 3 3-3',scan:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M7 12h3l2-5 2 10 2-5h2',flask:'M9 3h6m-5 0v6l-6 10v2h16v-2L14 9V3M7 15h10',store:'M3 9l2-6h14l2 6M4 9v12h16V9M9 21v-8h6v8M3 9c0 4 4 4 4 0 0 4 5 4 5 0 0 4 5 4 5 0 0 4 4 4 4 0',chart:'M4 3v18h17M8 16v-4m5 4V8m5 8V5',arrow:'M5 12h14m-5-5 5 5-5 5',plus:'M12 5v14M5 12h14',shield:'M12 3 3 6v6c0 5 9 9 9 9s9-4 9-9V6zM8 12l3 3 5-6',play:'m8 5 11 7-11 7z',check:'m5 12 4 4L19 6',close:'m6 6 12 12M18 6 6 18',export:'M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',loop:'M4 10a8 8 0 0 1 14-4l3 3M21 3v6h-6M20 14A8 8 0 0 1 6 18l-3-3M3 21v-6h6',lock:'M5 10h14v11H5zM8 10V6a4 4 0 0 1 8 0v4M12 14v3',info:'M12 11v6m0-10v1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',menu:'M4 6h16M4 12h16M4 18h16'};
const icon=(n,s=18)=>`<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const btn=(label,action,style='secondary',extra='')=>`<button class="btn ${style}" data-action="${action}" ${extra}>${label}</button>`;
const pill=(text,style='')=>`<span class="pill ${style}">${text}</span>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Browser storage unavailable. Keep this tab open to retain your session.')}}
function audit(text){state.audit.unshift({text,time:new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})});save()}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200)}
const tabs=[['overview','grid','Pilot overview'],['returns','inbox','Return capture'],['diagnostics','scan','Fit diagnostics'],['experiment','flask','Experiment lab'],['storefront','store','Employee storefront'],['impact','chart','Impact & governance']];
function nav(v){view=tabs.some(t=>t[0]===v)?v:'overview';location.hash=view;document.body.classList.remove('menu-open');render();window.scrollTo(0,0)}
function header(k,title,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`}
function panel(title,sub,body,action=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>${body}</section>`}
function metric(label,value,note,ic='chart'){return `<div class="metric"><div class="metric-top">${label}${icon(ic,17)}</div><strong>${value}</strong><small>${note}</small></div>`}
function render(){document.body.dataset.view=view;const name=tabs.find(t=>t[0]===view)?.[2]||'Pilot overview';$('#app').innerHTML=`<aside><div class="brand"><span class="mark" aria-hidden="true"><i></i><i></i></span><div><strong>RE-THREAD<span class="brand-period" aria-hidden="true">+</span></strong><small>OPERATIONS EXTENSION</small></div></div><div class="workspace"><div class="brand-pair"><div class="prowear-wordmark">PROWEAR<span>SOLUTIONS</span></div><span class="brand-cross">×</span><div class="nova-wordmark">nova<span>threads</span><i>✳</i></div></div><div class="workspace-caption"><span class="dot"></span> Shared intelligence workspace</div></div><div class="navlabel">THE SHARED WORKSPACE <span>01—06</span></div><nav>${tabs.map(([id,ic,label])=>`<button class="navbtn ${view===id?'active':''}" data-nav="${id}" ${view===id?'aria-current="page"':''}>${icon(ic)}${label}${id==='diagnostics'?`<span class="count">${diagnostics(state.records,state.orders).filter(x=>x.priority==='High').length}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="side-note"><span class="dot"></span> &nbsp;Competition demo<br>Synthetic data · local session<br><button class="text-link" style="padding:8px 0" data-action="about">Case scope & assumptions ↗</button></div><div class="team"><span class="avatar">RT</span><div><b>Integration team</b><small>ProWear + NovaThreads</small></div></div></div></aside><main><div class="topbar"><button class="mobile-menu iconbtn" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><div class="crumb"><b>PROWEAR <span class="crumb-cross">×</span> <em>novathreads</em></b><span class="crumb-page">/ &nbsp;${name}</span></div><div class="top-actions">${pill('<span class="dot"></span> D0–90 pilot','gray')}<button class="btn secondary small" data-action="reset">${icon('loop',14)} Reset demo</button><button class="btn dark small" data-action="demo">${icon('play',13)} Present demo</button></div></div><div class="content">${({overview,returns:returnsView,diagnostics:diagnosticView,experiment:experimentView,storefront,impact:impactView}[view]||overview)()}<div class="footer"><span>${icon('shield',13)} Nova autonomy preserved. Four-week sourcing · Shopify · dedicated consumer 3PL.</span><span>PROJECT RE-THREAD &nbsp;/&nbsp; Case!Please &nbsp; © 2026</span></div></div></main>`;bindForms()}
function overview(){const ds=diagnostics(state.records,state.orders),high=ds.filter(d=>d.priority==='High');return header('PROWEAR SOLUTIONS × NOVATHREADS / SHARED INTELLIGENCE','Better returns. Better decisions.','Turn every return into a signal. ProWear precision, NovaThreads instinct.',btn(icon('plus',15)+' Capture return','capture',''))+`<section class="hero merger-hero"><div class="thread-art" aria-hidden="true"><i class="thread thread-corporate"></i><i class="thread thread-nova"></i><span class="thread-star">✳</span></div><div class="hero-copy"><div class="eyebrow"><span class="hero-edition">P × N / 01</span> TWO BRANDS. ONE INTELLIGENCE LAYER.</div><h2>A smarter fit starts with<br><em>listening to what comes back.</em></h2><p>Spot repeated fit and fabric issues, test the right correction, and scale only what creates verified value.</p></div><div class="hero-badge target-tag"><span class="tag-label">THE NEXT FIT / PILOT TARGET</span><strong>25<span style="font-size:22px">%</span> → 22<span style="font-size:22px">%</span></strong><small>Case baseline → illustrative test target</small><span class="tag-stitch" aria-hidden="true"></span></div></section><div class="metrics">${metric('Returns captured',state.records.length,'Across '+(1000+state.orders.filter(o=>o.status==='Delivered').length).toLocaleString()+' synthetic shipped units','inbox')}${metric('Priority patterns',high.length,'SKU × size groups requiring review','scan')}${metric('Test target','−3.0 pp','12% relative reduction · model','flask')}${metric('Modeled annual uplift',money(impact(state.scenario)),'Scenario, not realized savings','chart')}</div><div class="grid">${panel('From returns to retained value','Illustrative pilot trajectory · not observed performance',`<div class="panel-body"><svg class="chart" viewBox="0 0 580 190" role="img" aria-label="Illustrative return rate declines from 25 percent to 22 percent while control remains at 25 percent"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ddd6f6"/><stop offset="1" stop-color="#fff"/></linearGradient></defs>${[30,70,110,150].map((y,i)=>`<line x1="35" y1="${y}" x2="555" y2="${y}" stroke="#e9eeeb" stroke-dasharray="3 5"/><text x="0" y="${y+4}">${26-i*2}%</text>`).join('')}<path d="M45 50L145 64L245 74L345 94L445 108L545 110V151H45Z" fill="url(#area)"/><path d="M45 50L145 50L245 50L345 50L445 50L545 50" stroke="#adb8bf" stroke-width="2" stroke-dasharray="5 5" fill="none"/><path d="M45 50C95 50 105 63 145 64S205 68 245 74S305 85 345 94S405 104 445 108S505 110 545 110" stroke="#6250bd" stroke-width="3" fill="none"/><circle cx="545" cy="110" r="5" fill="#6250bd"/><text x="518" y="95" style="fill:#6250bd;font-weight:700">22.0%</text>${['Baseline','W2','W4','W6','W8','W12'].map((w,i)=>`<text x="${30+i*100}" y="178">${w}</text>`).join('')}</svg><div class="legend"><span><i style="background:#6250bd"></i>Treatment scenario</span><span><i style="background:#aeb9bd"></i>Control scenario</span></div><div class="insight"><b>The decision rule:</b> lower returns are useful only when retained contribution improves and customer protections remain intact.</div></div>`,btn('Open experiment ↗','experiment','secondary small'))}${panel('Signals worth a closer look','Explainable patterns, ready for human review',high.slice(0,3).map(d=>`<button class="signal" style="width:100%;text-align:left" data-signal="${d.key}"><span class="signal-icon">${icon('scan',17)}</span><div><h3>${d.product.name} · ${d.size}</h3><p>${d.count} × ${d.reason.toLowerCase()}<br>${pct(d.rate)} returned · ${d.shipped} shipped</p></div>${pill('Review','amber')}</button>`).join(''))}</div>${panel('One connected diagnostic loop','A practical translation of the integration pilot',`<div class="loop">${[['01','Capture','SKU, size, reason and channel.'],['02','Identify','Repeated fit and fabric signals.'],['03','Correct','Approve a page or supplier fix.'],['04','Test','Compare mature control cohorts.'],['05','Track','Contribution, repeat and guardrails.']].map(x=>`<div class="loop-step"><div class="step-no">${x[0]}</div><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div>`,pill('HUMAN-IN-THE-LOOP'))}`}
function returnsView(){const recent=[...state.records].reverse().filter(r=>(r.order+' '+r.sku+' '+r.reason).toLowerCase().includes(search.toLowerCase())&&(filter==='all'||r.channel===filter));return header('01 / CAPTURE','Every return has a reason.','Capture a structured signal without changing refund eligibility or customer rights.',btn(icon('export',14)+' Export records','export','secondary'))+`<div class="grid">${panel('Register a return','One return per order / SKU · all fields marked * are required',`<div class="panel-body"><form id="capture-form"><div class="formgrid"><label>Order ID *<input name="order" placeholder="e.g. ORD-2401" required maxlength="40"></label><label>Sales channel *<select name="channel"><option>D2C</option><option>Employee</option></select></label><label>Product / SKU *<select name="sku">${products.map(p=>`<option value="${p.sku}">${p.sku} · ${p.name}</option>`).join('')}</select></label><label>Purchased size *<select name="size">${['S','M','L','XL'].map(s=>`<option ${s==='M'?'selected':''}>${s}</option>`).join('')}</select></label><label class="full">Primary return reason *<select name="reason">${reasons.map(r=>`<option>${r}</option>`).join('')}</select></label><label class="full">Customer observation<textarea name="note" maxlength="240" placeholder="e.g. Tight at shoulders despite following the size chart."></textarea></label></div><div class="form-actions"><button class="btn" type="submit">${icon('plus',14)} Save return & analyze</button><span class="note">Refund rights unchanged</span></div><p id="form-error" class="error" role="alert"></p></form></div>`)}${panel('What is coming back?','Current synthetic cohort · counts update with capture',`<div class="panel-body">${reasons.map(r=>{const n=state.records.filter(x=>x.reason===r).length;return `<div class="reasonbar"><div class="row"><span>${r}</span><b>${n}</b></div><div class="meter"><i style="width:${n/state.records.length*100}%"></i></div></div>`}).join('')}<div class="insight">Channel and order ID travel with each return. Employee purchases feed the same diagnostic engine.</div></div>`)}</div>${panel('Return ledger',`${recent.length} matching records · latest 25 shown`,`<div class="panel-body"><div class="toolbar"><input id="search" aria-label="Search returns" value="${esc(search)}" placeholder="Search order, SKU or reason…"><select id="channel-filter" aria-label="Filter channel" style="width:160px"><option value="all">All channels</option><option ${filter==='D2C'?'selected':''}>D2C</option><option ${filter==='Employee'?'selected':''}>Employee</option></select></div></div><div class="table-wrap"><table><thead><tr><th>Return / order</th><th>SKU</th><th>Size</th><th>Reason</th><th>Channel</th><th>Date</th></tr></thead><tbody>${recent.slice(0,25).map(r=>`<tr><td><b>${esc(r.id)}</b><small>${esc(r.order)}</small></td><td>${r.sku}</td><td>${r.size}</td><td>${esc(r.reason)}</td><td>${pill(r.channel,'gray')}</td><td>${r.date}</td></tr>`).join('')}</tbody></table>${recent.length?'':'<div class="empty">No matching returns. Try a different search.</div>'}</div>`)}`}
function diagnosticView(){const ds=diagnostics(state.records,state.orders),d=ds.find(d=>d.key===selected)||ds[0],a=state.actions.find(x=>x.key===d.key);return header('02–03 / IDENTIFY & CORRECT','Find the pattern. Fix the cause.','SKU × size cohorts make repeated issues visible. Every recommendation requires human review.',pill('EXPLAINABLE RULE ENGINE'))+`<div class="grid">${panel('Return concentration','One unit per shipped order · base cohort + delivered demo employee orders',`<div class="table-wrap"><table><thead><tr><th>Product / size</th><th>Returns</th><th>Rate</th><th>Signal</th><th></th></tr></thead><tbody>${ds.map(x=>`<tr style="${x.key===d.key?'background:#f0ecfb':''}"><td><b>${x.product.name}</b><small>${x.sku} · Size ${x.size}</small></td><td>${x.returns} / ${x.shipped}</td><td>${pct(x.rate)}<div class="meter"><i class="${x.priority==='High'?'warm':''}" style="width:${x.rate*100}%"></i></div></td><td>${pill(x.priority,x.priority==='High'?'amber':'gray')}</td><td><button class="text-link" data-signal="${x.key}">Inspect →</button></td></tr>`).join('')}</tbody></table></div>`)}<div>${panel('Signal evidence',`${d.sku} / ${d.size} · ${d.product.name}`,`<div class="panel-body">${pill(d.priority==='High'?'Priority review':'Monitor / review',d.priority==='High'?'amber':'gray')}<h2 style="margin:16px 0 8px">${d.reason} repeats ${d.count} times.</h2><p class="note">${d.count} of ${d.returns} returns (${pct(d.share)}) share this reason. ${d.returns} of ${d.shipped} shipped units returned (${pct(d.rate)}).</p><div class="sourceblock"><b>Why it was flagged</b><br>Repeated reason ≥ 5: <b>${d.repeated?'Yes':'No'}</b><br>Return rate ≥ 30%: <b>${d.elevated?'Yes':'No'}</b><br>These are prototype thresholds, not trained-model confidence or proof of causation.</div><hr class="thin-rule"><div class="eyebrow">SUGGESTED INTERVENTION</div><h3>${d.kind==='Supplier specification'?'Audit fabric / quality specification':'Review size chart & fit guidance'}</h3><p class="note" style="margin:9px 0 15px">${d.kind==='Supplier specification'?'Check material batch, composition and finish against approved specifications. Require supplier evidence before releasing a correction.':'Measure retained samples and compare the published chart. Add a clear fit note only after the product team validates the discrepancy.'}</p>${a?pill(a.status==='approved'?'Correction approved':'Draft awaiting approval',a.status==='approved'?'':'amber'):btn('Create correction draft','draft','','data-key="'+d.key+'"')}<p class="trace" style="margin-top:15px">Do not infer root cause from return reasons alone. Customer intent, exposure and batch effects may confound the pattern.</p></div>`)}${state.actions.length?`<div class="action-list">${state.actions.map(a=>`<article class="action-card"><div class="split-title"><h3>${a.key}</h3>${pill(a.status,'gray')}</div><p>${esc(a.correction)}</p><p>Owner: ${a.owner} · Scope: ${a.kind}</p>${a.status==='draft'?btn('Review & approve','review','secondary small',`data-key="${a.key}"`):btn('Design experiment →','experiment','secondary small')}</article>`).join('')}</div>`:''}</div></div>`}
function experimentView(){const r=experimentResult(),g=gate(state),approved=state.actions.some(x=>x.status==='approved');return header('04 / TEST','Evidence before expansion.','Matched control and treatment cohorts. Same return window. No changes to customer rights.',btn(state.experiment?'Review loaded results':'Load synthetic test results','run-experiment','',approved?'':'disabled'))+`<section class="hero"><div><div class="eyebrow">CONTROLLED PILOT / D0–90</div><h2>Does the correction work<br>without creating another problem?</h2><p>Prototype design: matched SKU cohorts, 2,000 shipped orders per arm, 30-day matured returns. Results are simulated, not live experimentation.</p></div><div class="hero-numbers"><div>25%<small class="mini-label">CONTROL</small></div><span>→</span><div>22%<small class="mini-label">TREATMENT</small></div></div></section>${!approved?`<div class="secure-band">${icon('lock')} Approve a correction in Fit diagnostics to unlock the experiment.</div>`:''}<div class="metrics">${metric('Control return rate',state.experiment?'25.0%':'—',state.experiment?'500 / 2,000 shipped orders':'Awaiting approved correction')}${metric('Treatment return rate',state.experiment?'22.0%':'—',state.experiment?'440 / 2,000 shipped orders':'Target: 22%, not yet loaded')}${metric('Absolute reduction',state.experiment?'3.0 pp':'—','12% relative reduction when loaded')}${metric('Pilot net contribution',state.experiment?money(r.net):'—','60 × $35 − $1,500 test cost')}</div><div class="grid equal">${panel('Experiment readout','Synthetic, mature cohorts · 30-day observation window',`<div class="panel-body">${state.experiment?`<div class="statrow"><span>95% interval for reduction</span><b>${(r.lower*100).toFixed(2)}–${(r.upper*100).toFixed(2)} pp</b></div><div class="statrow"><span>Control repeat purchase</span><b>18% · 360 / 2,000</b></div><div class="statrow"><span>Treatment repeat purchase</span><b>19% · 380 / 2,000</b></div><div class="statrow"><span>Net retained contribution</span><b class="green">${money(r.net)}</b></div><div class="insight">The return-rate interval excludes zero in this synthetic example. Repeat purchase is descriptive only; no proven retention lift is claimed.</div><p class="trace" style="margin-top:14px">Unpooled normal approximation for two independent proportions. Real rollout needs randomization, power planning, matched exposure, complete return windows and review of SKU/batch effects.</p>`:`<div class="empty">${icon('flask',32)}<p style="margin-top:12px">Approve a correction, then load the demo experiment.</p></div>`}</div>`)}${panel('Customer-experience gates','Toggle a guardrail to demonstrate the stop condition',`<div class="panel-body"><div class="checklist">${[['refund','Refund rights unchanged','Same policy in both arms'],['delivery','Delivery parity maintained','96% on time in both arms · synthetic'],['csat','Customer satisfaction maintained','4.3 / 5 in both arms · synthetic'],['speed','Four-week sourcing protected','No compulsory warehouse migration']].map(([id,title,sub])=>`<label class="checkline"><input type="checkbox" data-guard="${id}" ${state.guardrails[id]?'checked':''}><span>${title}<small>${sub}</small></span></label>`).join('')}</div><div class="statusbox ${g.status==='hold'?'hold':''}" style="margin-top:24px"><div class="eyebrow">SCALE GATE</div><h3>${g.label}</h3><p class="note">${g.status==='pass'?'Positive test contribution and all guardrails pass. Human sign-off and field validation are still required.':g.status==='hold'?'Do not scale. Resolve the failed guardrail and rerun the comparison.':'No scale decision until a reviewed correction has mature test evidence.'}</p></div></div>`)}</div>`}
const art=(p)=>`<svg viewBox="0 0 180 190" aria-hidden="true"><ellipse cx="90" cy="177" rx="53" ry="6" fill="#d7d9d3"/>${p.type==='TROUSER'?`<path d="M55 18H125L136 165H95L90 74 84 165H43Z" fill="${p.color}"/><path d="M55 30h70M90 18v55M64 33l-12 27m65-27 12 27" stroke="#ffffff40" fill="none"/>`:`<path d="M65 23 39 35 12 83 38 98 52 76 49 165Q90 174 131 165L128 76 142 98 168 83 141 35 115 23Q90 38 65 23Z" fill="${p.color}"/><path d="m65 23 25 27 25-27M90 50v116M55 80l-3 85m73-85 3 85M100 60h19v20h-19z" fill="none" stroke="#ffffff60"/><path d="m66 24 7 30 17-10 17 10 7-30" fill="#ffffff25"/>${[65,85,105,125,145].map(y=>`<circle cx="92" cy="${y}" r="1.4" fill="#ffffffb0"/>`).join('')}`}</svg>`;
function storefront(){const e=employers.find(e=>e.id===state.session?.employer);return header('05 / PERMISSIONED EMPLOYEE COMMERCE','NovaThreads, by invitation.','An employer-enabled channel. Nova owns the catalogue; the consumer 3PL owns fulfilment.',state.session?btn('Lock storefront','logout','secondary'):pill(icon('lock',13)+' Access controlled'))+(!state.session?`<div class="grid equal">${panel('Verify pilot access','Simulated permission checks · no real credentials required',`<div class="panel-body"><div class="biglock">${icon('lock',30)}</div><h2>Private access. Clear permissions.</h2><p class="note" style="margin:12px 0 23px">Verify the employer agreement and employee roster before revealing the catalogue. Try North Studio to demonstrate a blocked employer.</p><form id="access-form"><label>Employer<select name="employer">${employers.map(e=>`<option value="${e.id}">${e.name}${e.approved?' · approved':' · permission pending'}</option>`).join('')}</select></label><label style="margin-top:17px">Employee ID<input name="employee" value="EMP-1042" required></label><p class="note" style="margin:12px 0">Demo roster ID: <b>EMP-1042</b>. This browser simulation is not production authentication.</p><button class="btn" type="submit">${icon('shield',15)} Verify & enter catalogue</button><p class="error" id="access-error" role="alert"></p></form></div>`)}${panel('Six gates. One accountable channel.','Mapped directly to the brand pilot',`<div class="panel-body">${[['01','Employer permission','Written agreement and eligible categories.'],['02','ProWear eligibility','Validate employee roster and entitlements.'],['03','Nova catalogue','Brand-approved products and validated sizing.'],['04','Employee opt-in','Personal payment or sponsor credit.'],['05','Consumer 3PL','Single-item fulfilment and normal returns.'],['06','Shared evidence','Contribution, repeat orders and service.']].map(x=>`<div class="phase"><span class="number">${x[0]}</span><div><b>${x[1]}</b><p>${x[2]}</p></div></div>`).join('')}</div>`)}</div>`:`<div class="secure-band">${icon('shield',20)}<span><b>${e.name}</b> · EMP-1042 · Verified demo access</span><span style="margin-left:auto">Sponsor balance: <b>${money(state.storeCredit)}</b></span></div><div class="hero"><div><div class="eyebrow">NOVATHREADS × PROWEAR / EMPLOYEE EDIT 001</div><h2>Designed for your <em>everyday.</em></h2><p>A curated capsule, approved by Nova. No public clearance pricing. No implied medical or uniform certification.</p></div><div class="hero-badge">${icon('store',45)}<small>Brand-approved catalogue</small></div></div><div class="productgrid">${products.slice(0,3).map(p=>`<article class="product"><div class="product-art" data-category="${p.type}">${pill('EMPLOYEE EXCLUSIVE')}${art(p)}</div><div class="product-info"><div class="eyebrow">NOVATHREADS / EVERYDAY SERIES</div><div class="split-title"><h3>${p.name}</h3><b>${money(p.price)}</b></div><p class="note">${p.sku} · illustrative pilot price</p><label>Choose size<select id="size-${p.sku}">${['S','M','L','XL'].map(s=>`<option ${s==='M'?'selected':''}>${s}</option>`).join('')}</select></label>${p.sku==='NV-101'?`<p class="trace" style="margin-top:10px">${state.actions.find(a=>a.key==='NV-101-M'&&a.status==='approved')?'Reviewed correction: check shoulder measurements against the revised chart. Fit validation remains in pilot.':'Fit signal under review: consult garment measurements before choosing a size.'}</p>`:''}${btn('Review order →','checkout','',`data-sku="${p.sku}"`)}</div></article>`).join('')}</div><p class="trace" style="margin:15px 0 25px">Illustrated products and prices are synthetic. No live Shopify, payments, employer identity or 3PL connection.</p>${panel('Employee order journey','Confirmed → dispatched → delivered → optional return',`<div class="table-wrap"><table><thead><tr><th>Order / product</th><th>Size</th><th>Employee / sponsor</th><th>Status</th><th>Next step</th></tr></thead><tbody>${state.orders.map(o=>`<tr><td><b>${o.id}</b><small>${o.sku}</small></td><td>${o.size}</td><td>${money(o.payable)} / ${money(o.credit)}</td><td>${pill(o.returned?'Return captured':o.status,'gray')}</td><td>${o.returned?'Sent to diagnostic loop':btn(o.status==='Confirmed'?'Simulate dispatch':o.status==='Dispatched'?'Simulate delivery':'Register return','order-step','secondary small',`data-order="${o.id}"`)}</td></tr>`).join('')}</tbody></table>${state.orders.length?'':'<div class="empty">Your demo orders will appear here. No payment is taken.</div>'}</div>`)}`)}
function impactView(){const s=state.scenario,net=impact(s),g=gate(state);return header('05 / TRACK & GOVERN','Value that can be defended.','Separate case facts, scenario economics and simulated evidence. All financial values are USD.',btn(icon('export',14)+' Export pilot report','report','secondary'))+`<div class="metrics">${metric('Annual scenario uplift',money(net),'Returns improvement model')}${metric('Employee pilot sales','$33,000','300 buyers × $110 order · model')}${metric('Pilot contribution','$8,250','25% before fixed pilot costs · model')}${metric('Mature channel hypothesis','$594,000','Annual contribution · not verified')}</div><div class="grid equal">${panel('Returns economics sandbox','Adjust assumptions · values are never reported as actual savings',`<div class="panel-body"><div class="formgrid"><label>Annual shipped orders<input type="number" id="sc-orders" value="${s.orders}" min="1" max="100000000" step="1"></label><label>Retained contribution / avoided return ($)<input type="number" id="sc-contribution" value="${s.contribution}" min="0" max="1000"></label><label class="full">Return-rate improvement: <span id="improvement-label">${s.improvement}</span> percentage points<input type="range" id="sc-improvement" min="0" max="10" step="0.5" value="${s.improvement}"></label><label class="full">Annual implementation cost ($)<input type="number" id="sc-cost" value="${s.cost}" min="0" max="100000000"></label></div><div class="statusbox" style="margin-top:20px"><span class="note">Modeled annual uplift</span><h2 id="annual-output" style="font-size:30px;margin:8px 0">${money(net)}</h2><p class="trace" id="formula-output">${s.orders.toLocaleString()} × ${s.improvement}% × ${money(s.contribution)} − ${money(s.cost)}</p></div><div class="sourceblock">Deck model: 2M × 3pp × $35 − $400k = $1.7M. This uses the explicit appendix formula; the extra “pilot contribution” phrase on the integration page has no quantified deduction. The $600 demo test net is not added to annual synergy.</div></div>`)}${panel('Employer channel economics','Commercial hypothesis from section 05',`<div class="panel-body"><div class="statrow"><span>Participating employers</span><b>3</b></div><div class="statrow"><span>Eligible employees</span><b>2,000</b></div><div class="statrow"><span>Participation assumption</span><b>15% → 300 buyers</b></div><div class="statrow"><span>Average order value</span><b>$110</b></div><div class="statrow"><span>Contribution before fixed costs</span><b>$33,000 × 25% = $8,250</b></div><div class="insight"><b>Mature hypothesis:</b> 150,000 eligible × 15% × 1.2 orders × $110 × 20% = $594,000 annually. Not a signed contract or achieved run rate.</div><p class="trace" style="margin-top:15px">Sponsor credit is a payment source, not a margin uplift. Validate funding, redemption, return processing and incremental acquisition costs before claiming contribution.</p></div>`)}</div><div class="grid equal">${panel('Integration boundaries','Protect the capability being acquired',`<div class="panel-body"><div class="phase"><span class="number">01</span><div><b>Integrate controls</b><p>Finance reporting, governance and approved common-spec procurement.</p></div></div><div class="phase"><span class="number">02</span><div><b>Preserve Nova</b><p>Four-week trend sourcing, Shopify checkout, brand decisions and consumer 3PL.</p></div></div><div class="phase"><span class="number">03</span><div><b>Stage the rollout</b><p>D0–90 diagnostics → D91–180 evergreen / procurement tests → D181–365 scale only validated pilots.</p></div></div><div class="statusbox ${g.status==='hold'?'hold':''}" style="margin-top:18px"><h3>${g.label}</h3><p class="note">No automatic rollout or acquisition approval.</p></div></div>`)}${panel('Session audit trail','Browser-local actions · resettable demonstration',`<div class="panel-body">${state.audit.length?state.audit.slice(0,8).map(a=>`<div class="phase"><span class="number">${a.time}</span><p class="note">${esc(a.text)}</p></div>`).join(''):'<p class="note">Actions taken in the pilot will appear here.</p>'}<div class="sourceblock"><b>Evidence register</b><br>CASE: 25% Nova return rate; four-week sourcing.<br>MODEL: 22% target, $1.7M annual return uplift, $8,250 early channel contribution.<br>DEMO: all products, individual returns, employers, cohorts and outcomes.<br>Production authentication, data ingestion and trained AI are outside this prototype.</div></div>`)}</div>`}
function showModal(title,body,footer=''){const m=$('#modal');m.innerHTML=`<div class="modal-top"><h3>${title}</h3><button class="iconbtn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-bottom">${footer}</div>`:''}`;if(!m.open)m.showModal()}
function close(){$('#modal').close()}
function download(name,content,type){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function bindForms(){
 $('#capture-form')?.addEventListener('submit',e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));const r=capture(state,data);audit(`Captured ${r.id}: ${r.sku} / ${r.size} / ${r.reason}`);selected=r.sku+'-'+r.size;render();toast('Return captured. Diagnostic patterns recalculated.')}catch(err){$('#form-error').textContent=err.message}});
 $('#access-form')?.addEventListener('submit',e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));state.session=authorize(d.employer,d.employee);audit('Verified demo employer permission and employee eligibility.');render();toast('Access verified. Nova employee catalogue unlocked.')}catch(err){$('#access-error').textContent=err.message}});
 $('#channel-filter')?.addEventListener('change',e=>{filter=e.target.value;render()});
 $('#search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)});
 document.querySelectorAll('[data-guard]').forEach(el=>el.addEventListener('change',()=>{state.guardrails[el.dataset.guard]=el.checked;audit(`Guardrail ${el.dataset.guard}: ${el.checked?'pass':'failed'}`);render()}));
 ['orders','contribution','improvement','cost'].forEach(k=>$('#sc-'+k)?.addEventListener('input',e=>{if(!e.target.checkValidity()||e.target.value==='')return;state.scenario[k]=Number(e.target.value);save();$('#annual-output').textContent=money(impact(state.scenario));$('#improvement-label').textContent=state.scenario.improvement;$('#formula-output').textContent=`${state.scenario.orders.toLocaleString()} × ${state.scenario.improvement}% × ${money(state.scenario.contribution)} − ${money(state.scenario.cost)}`;document.querySelector('.metric strong').textContent=money(impact(state.scenario))}));
}
const tour=[
 ['overview','One return. A better operating decision.','The merger should share intelligence without taking away Nova’s speed. This pilot shows how a return becomes a measurable correction.','Start with the 25% case baseline and 22% modeled target. The dashboard data is synthetic.','Explore the pilot'],
 ['returns','Capture the signal, not just the refund.','Record SKU, purchased size, reason and channel. We will capture a new medium Oxford return with a “Too small” reason.','The demo action creates a traceable return record and recalculates the pattern.','Capture demo return'],
 ['diagnostics','Find a repeated size-level issue.','The Oxford medium cohort has a concentrated “Too small” signal. Inspect the numerator, shipped denominator and repeated-reason count.','The engine proposes a size-chart review. A human validates garment measurements before approval.','Approve demo correction'],
 ['experiment','Test the correction against a control.','Load two synthetic mature cohorts: 500 / 2,000 control returns versus 440 / 2,000 treatment returns.','60 avoided returns × $35 − $1,500 test expense = $600 pilot net. A failed customer-experience gate blocks scale.','Load test results'],
 ['storefront','Connect the employee channel.','An approved employer and eligible employee unlock Nova’s private catalogue. Normal return handling stays with a specialized consumer 3PL.','The action opens Atlas Design Co. access for EMP-1042. You can then order, dispatch, deliver and send a return into diagnostics.','Unlock employee demo'],
 ['impact','Scale evidence, not assumptions.','The annual model is $1.7M, separate from $600 of synthetic pilot net. The employee channel is a separate commercial hypothesis.','Close with the governance rule: positive incremental contribution, no customer-experience decline and verified employer permissions.','Finish presentation']
];
function present(){const t=tour[demoStep];nav(t[0]);showModal('GUIDED DEMO · '+(demoStep+1)+' OF '+tour.length,`<div class="eyebrow">PROJECT RE-THREAD / CASE!PLEASE</div><h2>${t[1]}</h2><p class="note">${t[2]}</p><div class="demo-callout"><b>Presenter cue</b><br>${t[3]}</div><div class="demosteps">${tour.map((_,i)=>`<i class="${i<=demoStep?'on':''}"></i>`).join('')}</div><p class="trace">The next button performs the named demo action. You can close this guide anytime to explore the screen.</p>`,`${btn('Exit guide','close','secondary')}${btn(t[4]+' '+icon('arrow',14),'demo-next','')}`)}
function advanceDemo(){try{if(demoStep===1){const order='DEMO-'+(state.records.length+1);capture(state,{order,sku:'NV-101',size:'M',reason:'Too small',channel:'D2C',note:'Guided demo: shoulders tighter than published sizing.'});audit('Guided demo captured Oxford M return.');selected='NV-101-M'}if(demoStep===2){let a=state.actions.find(a=>a.key==='NV-101-M');if(!a){a={key:'NV-101-M',kind:'Sizing guidance',owner:'Nova product lead',correction:'Validate garment shoulder measurements and revise the size chart.',status:'draft'};state.actions.push(a)}a.status='approved';a.evidence='Simulated product-team measurement review for presentation.';audit('Guided demo simulated human approval of Oxford M correction.')}if(demoStep===3){state.experiment=true;audit('Loaded synthetic control and treatment results.')}if(demoStep===4){state.session=authorize('atlas','EMP-1042');audit('Guided demo verified Atlas employee access.')}save();if(demoStep===5){close();render();toast('Demo complete. Explore the live workflows or export the pilot report.');return}demoStep++;present()}catch(e){toast(e.message)}}
document.addEventListener('click',e=>{const n=e.target.closest('[data-nav]');if(n){nav(n.dataset.nav);return}const signal=e.target.closest('[data-signal]');if(signal){selected=signal.dataset.signal;nav('diagnostics');return}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
 if(action==='menu'){document.body.classList.toggle('menu-open');return}if(action==='close'){close();return}if(action==='capture'){nav('returns');return}if(action==='experiment'){nav('experiment');return}if(action==='demo'){demoStep=0;present();return}if(action==='demo-next'){advanceDemo();return}
 if(action==='reset'){showModal('Reset this demonstration?',`<h2>Start with a clean pilot.</h2><p class="note">This clears returns you added, corrections, employee orders, scenario changes and audit activity in this browser. The original synthetic dataset will be restored.</p>`,btn('Keep session','close','secondary')+btn('Reset demo data','confirm-reset',''));return}
 if(action==='confirm-reset'){state=seedState();selected='NV-101-M';search='';filter='all';save();close();nav('overview');toast('Demo restored to its starting state.');return}
 if(action==='draft'){const d=diagnostics(state.records,state.orders).find(x=>x.key===b.dataset.key);if(state.actions.some(a=>a.key===d.key))return;state.actions.push({key:d.key,kind:d.kind,owner:d.kind==='Supplier specification'?'Nova quality lead':'Nova product lead',correction:d.kind==='Supplier specification'?'Audit batch composition, finish and material specifications.':'Validate garment measurements and revise the size chart / fit note.',status:'draft'});audit('Created correction draft for '+d.key);render();toast('Draft created. Human review required.');return}
 if(action==='review'){const a=state.actions.find(a=>a.key===b.dataset.key);showModal('Human review · '+a.key,`<h2>Validate before publishing.</h2><p class="note">${esc(a.correction)}</p><label style="margin-top:20px">Review evidence *<textarea id="review-evidence" placeholder="Record the sample measurement or supplier audit finding."></textarea></label><label class="checkline" style="margin-top:16px"><input id="review-check" type="checkbox"><span>I have reviewed the evidence for this simulated correction.</span></label><p id="review-error" class="error" role="alert"></p>`,btn('Cancel','close','secondary')+btn('Approve correction','approve','',`data-key="${a.key}"`));return}
 if(action==='approve'){if(!$('#review-check').checked||$('#review-evidence').value.trim().length<10){$('#review-error').textContent='Add at least 10 characters of evidence and confirm your review.';return}const a=state.actions.find(a=>a.key===b.dataset.key);a.status='approved';a.evidence=$('#review-evidence').value.trim().slice(0,1000);audit('Human review approved correction '+a.key);close();render();toast('Correction approved. Experiment unlocked.');return}
 if(action==='run-experiment'){if(!state.actions.some(a=>a.status==='approved'))return;state.experiment=true;audit('Loaded synthetic 30-day control / treatment cohorts.');render();toast('Synthetic experiment loaded. Inspect confidence and guardrails.');return}
 if(action==='logout'){state.session=null;save();render();return}
 if(action==='checkout'){const p=products.find(p=>p.sku===b.dataset.sku),size=$('#size-'+p.sku).value;showModal('Review employee order',`<div class="eyebrow">NOVA / SIMULATED CHECKOUT</div><h2>${p.name}</h2><p class="note">${p.sku} · Size ${size} · Specialized consumer 3PL</p><div class="statrow"><span>Order total</span><b>${money(p.price)}</b></div><label class="checkline" style="margin:20px 0"><input type="checkbox" id="use-credit" ${state.storeCredit>0?'checked':'disabled'}><span>Use sponsor balance (${money(state.storeCredit)} available)</span></label><div class="statrow"><span>Employee pays</span><b id="payable">${money(p.price-Math.min(state.storeCredit,p.price))}</b></div><p class="trace" style="margin:14px 0">No real payment. Sponsor credit and employee payment together fund the $110 order; credit does not create extra revenue.</p><label class="checkline"><input type="checkbox" id="order-consent"><span>I opt in to this simulated purchase. Standard return rights apply.</span></label><p id="checkout-error" class="error" role="alert"></p>`,btn('Cancel','close','secondary')+btn('Place demo order','place-order','',`data-sku="${p.sku}" data-size="${size}"`));$('#use-credit').onchange=()=>$('#payable').textContent=money(p.price-($('#use-credit').checked?Math.min(state.storeCredit,p.price):0));return}
 if(action==='place-order'){if(!$('#order-consent').checked){$('#checkout-error').textContent='Confirm your opt-in to place the simulated order.';return}try{const o=placeOrder(state,b.dataset.sku,b.dataset.size,$('#use-credit').checked);audit(`Placed ${o.id}: employee ${money(o.payable)}, sponsor ${money(o.credit)}.`);close();render();toast(o.id+' confirmed. No payment taken.')}catch(err){$('#checkout-error').textContent=err.message}return}
 if(action==='order-step'){const o=state.orders.find(x=>x.id===b.dataset.order);if(o.returned)return;if(o.status==='Confirmed'){o.status='Dispatched';audit(o.id+' handed to consumer 3PL.');render();toast('Consumer 3PL dispatch simulated.')}else if(o.status==='Dispatched'){o.status='Delivered';audit(o.id+' delivery simulated.');render();toast('Delivery simulated. Return handling is now available.')}else{showModal('Return to the diagnostic loop',`<h2>${o.id}</h2><p class="note">${o.sku} · Size ${o.size}. Standard refund eligibility is unchanged.</p><label style="margin-top:18px">Reason<select id="employee-reason">${reasons.map(r=>`<option>${r}</option>`).join('')}</select></label><p class="trace" style="margin-top:16px">The return will appear in the shared ledger. Refund processing would be handled by Shopify / the consumer 3PL in production; no money moves in this demo.</p>`,btn('Cancel','close','secondary')+btn('Capture return','employee-return','',`data-order="${o.id}"`))}return}
 if(action==='employee-return'){const o=state.orders.find(x=>x.id===b.dataset.order);try{capture(state,{order:o.id,sku:o.sku,size:o.size,reason:$('#employee-reason').value,channel:'Employee',note:'Employee storefront return · consumer 3PL'});o.returned=true;audit(o.id+' returned; added to shared fit diagnostic loop.');selected=o.sku+'-'+o.size;close();nav('diagnostics');toast('Employee return captured. Inspect the updated SKU / size signal.')}catch(err){toast(err.message)}return}
 if(action==='export'){const cols=['id','order','sku','size','reason','channel','date','note'];const safe=v=>{let t=String(v??'');if(/^[=+@\-\t\r]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"'};download('rethread-return-ledger.csv',cols.join(',')+'\n'+state.records.map(r=>cols.map(k=>safe(r[k])).join(',')).join('\n'),'text/csv;charset=utf-8');toast('Return ledger exported.');return}
 if(action==='report'){download('rethread-pilot-report.json',JSON.stringify({title:'RE-THREAD prototype evidence report',generated:new Date().toISOString(),disclaimer:'Synthetic demonstration; not verified business outcomes.',caseFacts:{returnRate:.25,sourceCycleWeeks:4},scenario:state.scenario,modeledAnnualUplift:impact(state.scenario),diagnostics:diagnostics(state.records,state.orders).map(({product,...d})=>d),corrections:state.actions,experiment:state.experiment?experimentResult():null,guardrails:state.guardrails,scaleGate:gate(state),orders:state.orders,audit:state.audit},null,2),'application/json');toast('Pilot evidence report exported.');return}
 if(action==='about'){showModal('Case scope & implementation',`<div class="eyebrow">THE FABRIC OF A MERGER</div><h2>Share intelligence.<br>Preserve independence.</h2><p class="note">This prototype implements sections <b>04 | Integration</b> and <b>05 | Brand</b> on PDF pages 6–7 of the supplied Project RE-THREAD deck.</p><div class="sourceblock"><b>Included:</b> return capture, repeated SKU / size signals, reviewed corrections, controlled-test readout, contribution and customer-experience gates, employer permission simulation, employee ordering, 3PL status simulation and return feedback.<br><br><b>Not connected:</b> real customer records, Shopify checkout, payments, employer identity, supplier systems or a trained AI model. All sample data is synthetic and stored only in this browser.</div><p class="note" style="margin-top:15px">Aarryan Kumar Khatri · Aditya Kumar · Kunal · Vibhu Vedant Goel<br><b>Case!Please · FMA Gargi × FIC DDUC</b></p>`,btn('Back to workspace','close',''));return}
});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(v!==view){view=tabs.some(t=>t[0]===v)?v:'overview';render()}});render();
